const stages=[["Early discovery","Test whether the need, problem or opportunity exists before committing heavily."],["Initial launch","Coordinate first access, first users or first transaction and collect early signals."],["Growth and scaling","Expand reach or capacity while protecting quality, trust and unit economics."],["Established operation","Improve reliability, efficiency, retention, governance or defensibility."],["Decline or disruption","Respond to weakening performance, substitution, shocks or loss of relevance."]];
const stakeholderModes=[["Solo decision-maker","One primary actor makes the decision but depends on external responses."],["Buyer and seller","A bilateral exchange with different interests, information and walk-away options."],["Multi-party coalition","Several parties have different incentives, vetoes and coordination costs."],["Group and network","Peer influence, norms, reputation and collective action shape choices."],["Institution and gatekeepers","Formal procedures, approvers, platform rules or regulators shape access."]];
const environments=[["Physical / local","In-person access, location, operating hours, travel and local infrastructure matter."],["Digital / platform-mediated","Discovery, ranking, platform rules, data and digital trust shape the interaction."],["Hybrid / omnichannel","Participants move between physical and digital touchpoints; handoffs can fail."],["Regulated / institution-led","Eligibility, formal approval, documentation, oversight and jurisdiction matter."],["Cross-border / distributed","Language, time zones, currencies, logistics and local institutional differences matter."]];
const pressures=[["Resource-constrained","Limited budget, staff, time or infrastructure make prioritisation important."],["Time-critical","A deadline or short opportunity window affects choices."],["High uncertainty","Evidence is incomplete, noisy or contested; assumptions need tests."],["Competitive / contested","Alternatives, rivals or opposing stakeholders can react strategically."]];
const combinations=[];for(let s=0;s<stages.length;s++)for(let m=0;m<stakeholderModes.length;m++)for(let e=0;e<environments.length;e++)for(let q=0;q<pressures.length;q++)combinations.push({stage:stages[s],stakeholders:stakeholderModes[m],environment:environments[e],pressure:pressures[q]});
const variants=[];for(let p=0;p<packs.length;p++)for(let k=0;k<139;k++)variants.push({packIndex:p,...combinations[Math.floor(k*combinations.length/139)]});variants.length=5000;
const dimensions={
 scale:{label:"Scale / reach",values:[["Individual","One person or one-to-one case"],["Small group / household","A small bounded group or household"],["Team / department","A defined team, unit or department"],["Organization / institution","An organization, institution or multi-unit system"],["Market / population / ecosystem","A broad market, population or interconnected ecosystem"]]},
 interaction:{label:"Interaction pattern",values:[["Direct one-to-one","Direct interaction between two primary participants"],["One-to-many","One actor communicates or serves many participants"],["Many-to-one","Many participants influence one decision-maker or recipient"],["Many-to-many network","Participants interact through a network"],["Sequential handoffs","Progress depends on a chain of people, stages or organizations"],["Platform-mediated matching","A platform, ranking system or marketplace mediates interaction"],["Repeated relationship","Participants interact repeatedly over time"],["Adversarial / contested","Participants have conflicting objectives or actively counter one another"]]},
 resources:{label:"Resource condition",values:[["Severely constrained","Critical resources are scarce; survival or access may be at risk"],["Tight budget / capacity","There is little spare money, time, staff or operating capacity"],["Balanced resources","Resources broadly match current requirements"],["Resource-rich","There is meaningful spare capacity or funding"],["Unevenly distributed resources","Some participants control resources others depend on"]]},
 uncertainty:{label:"Uncertainty profile",values:[["Known / evidence-rich","Reliable baseline information is available"],["Some unknowns","Key facts are known but important gaps remain"],["High uncertainty","Several important variables or responses are unknown"],["Ambiguous / conflicting evidence","Sources disagree or signals have multiple interpretations"],["Rapidly changing conditions","The situation changes faster than evidence can be gathered"]]},
 objective:{label:"Primary objective",values:[["Validate / learn","Find out whether an opportunity, claim or assumption is real"],["Acquire / attract","Gain customers, participants, support, access or attention"],["Negotiate / secure agreement","Reach an acceptable commitment or transaction"],["Coordinate / mobilize","Align people, resources or groups around action"],["Improve / optimize","Improve performance, efficiency, quality or reliability"],["Protect / defend","Preserve position, safety, trust, resources or continuity"],["Resolve / recover","Resolve conflict, failure, disruption or deterioration"],["Exit / transition","Leave, transfer, replace or move from the current arrangement"]]},
 feedback:{label:"Feedback speed",values:[["Immediate / live","Signals can be observed almost immediately after action"],["Daily / short-cycle","Useful feedback appears within a few days"],["Weekly / periodic","Signals emerge through a recurring review cycle"],["Milestone-based","Feedback arrives after a defined event, approval or delivery"],["Delayed / long-cycle","Consequences may take months or longer to become visible"]]}
};
const combinationCount=Object.values(dimensions).reduce((n,d)=>n*d.values.length,1);
const catalogueCount=variants.length*combinationCount;
function contextName(v){return packs[v.packIndex][1]+" — "+v.stage[0]+" · "+v.stakeholders[0]+" · "+v.environment[0]+" · "+v.pressure[0]}
function detailedBuild(index,geo={},chosen={}){
 const v=variants[Number(index)];if(!v)return null;
 const p=packs[v.packIndex],model=build(p,geo);
 model.meta.title=contextName(v)+" — STRATOS template";
 model.meta.templateId="stratos-context-"+index;
 model.meta.templatePath=[p[0],p[1],v.stage[0],v.stakeholders[0],v.environment[0],v.pressure[0]];
 model.meta.contextSpecificity="scenario-combination";
 model.situation.description=p[2]+". Stage: "+v.stage[0]+". Stakeholder structure: "+v.stakeholders[1]+" Operating environment: "+v.environment[1]+" Main pressure: "+v.pressure[1];
 model.situation.outcome=p[5]+". Specifically, "+v.stage[1];
 model.situation.boundary+=" Include the stage, stakeholder configuration, operating environment and pressure named in this template; validate which are actually present.";
 model.situation.contextStage=v.stage[0];model.situation.stakeholderConfiguration=v.stakeholders[0];model.situation.operatingEnvironment=v.environment[0];model.situation.primaryPressure=v.pressure[0];
 model.variables.push({id:id(),name:"Stage-specific readiness",description:v.stage[1],level:5,low:0,high:10,importance:8,direction:"mixed",confidence:"low",evidenceStatus:"assumption",notes:"Template hypothesis; establish a baseline."},{id:id(),name:"Stakeholder coordination burden",description:v.stakeholders[1],level:5,low:0,high:10,importance:7,direction:"negative",confidence:"low",evidenceStatus:"assumption",notes:"Map actual decision rights and incentives."},{id:id(),name:"Environment-specific access friction",description:v.environment[1],level:5,low:0,high:10,importance:7,direction:"negative",confidence:"low",evidenceStatus:"assumption",notes:"Measure access barriers in the chosen setting."},{id:id(),name:"Pressure intensity",description:v.pressure[1],level:5,low:0,high:10,importance:8,direction:"mixed",confidence:"low",evidenceStatus:"assumption",notes:"Estimate using evidence, not the template label."});
 model.actors.forEach(a=>{a.notes=(a.notes||"")+" Context configuration: "+v.stakeholders[0]+". Validate this role and its actual authority.";});
 model.events.push({id:id(),name:"Stage transition / pressure trigger",description:"A measurable signal indicates a change in stage or dominant pressure. Define an observable trigger and response.",when:2,kind:"conditional",likelihood:"unknown",status:"possible",actorId:model.actors[0]?.id||"",effects:{}});
 model.experiments.push({id:id(),name:"Context-fit test: "+v.environment[0],hypothesis:"The chosen operating environment changes access, trust or coordination friction.",measure:"Compare observed completion, delay, drop-off and cost across relevant touchpoints.",cost:"Low / bounded",speed:"Fast signal",status:"open"});
 const selected={};for(const [key,def] of Object.entries(dimensions)){const requested=chosen[key];selected[key]=def.values.some(x=>x[0]===requested)?requested:def.values[0][0];}
 model.meta.contextDimensions=selected;
 model.meta.templateCombinationId="stratos-"+index+"-"+Object.keys(selected).map(k=>dimensions[k].values.findIndex(x=>x[0]===selected[k])).join("");
 model.meta.templateCombinationCount=catalogueCount;
 model.situation.scale=selected.scale;model.situation.interactionPattern=selected.interaction;model.situation.resourceCondition=selected.resources;model.situation.uncertaintyProfile=selected.uncertainty;model.situation.primaryObjective=selected.objective;model.situation.feedbackCycle=selected.feedback;
 for(const [key,value] of Object.entries(selected)){const def=dimensions[key],detail=def.values.find(x=>x[0]===value)?.[1]||"";model.variables.push({id:id(),name:def.label,description:detail,level:5,low:0,high:10,importance:7,direction:"mixed",confidence:"low",evidenceStatus:"assumption",notes:"Selected template dimension. Replace with measured evidence and adjust to the real case."});}
 model.events.push({id:id(),name:"Feedback checkpoint: "+selected.feedback,description:"Collect an observable signal at the selected feedback cadence; record the action, sample, result and next decision.",when:1,kind:"conditional",likelihood:"unknown",status:"possible",actorId:model.actors[0]?.id||"",effects:{}});
 model.experiments.push({id:id(),name:"Objective-fit experiment: "+selected.objective,hypothesis:"A bounded action can produce evidence relevant to the selected objective.",measure:"Define one leading signal, baseline, sample, observation window and stop/change threshold.",cost:"Low / bounded",speed:selected.feedback,status:"open"});
 model.meta.title+=" — "+selected.scale+" · "+selected.objective;
 return model;
}
